from pathlib import Path
p=Path('workflow-engine.js')
s=p.read_text()

def replace_func(src,name,body):
    start=src.find(f'function {name}(')
    if start<0: raise RuntimeError(f'Missing {name}')
    brace=src.find('{',start); depth=0; quote=None; esc=False; i=brace
    while i<len(src):
        c=src[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in "'\"`": quote=c
            elif c=='{': depth+=1
            elif c=='}':
                depth-=1
                if depth==0: return src[:start]+body+src[i+1:]
        i+=1
    raise RuntimeError(f'Unterminated {name}')

anchor=s.find('function coverageMetrics(project)')
if anchor<0: raise RuntimeError('coverageMetrics anchor missing')
helpers=r'''
const SCOPE_KEYS=Object.freeze(['inputVersion','sourceSetVersion','requirementsVersion','testSuiteVersion','instructionVersion','iterationId','candidateId','baselineId','productId']);
function currentScope(project){return {inputVersion:project.job.CURRENT_INPUT_VERSION||null,sourceSetVersion:project.job.CURRENT_SOURCE_SET_VERSION||null,requirementsVersion:project.job.CURRENT_REQUIREMENTS_VERSION||null,testSuiteVersion:project.job.CURRENT_TEST_SUITE_VERSION||null,instructionVersion:project.job.CURRENT_INSTRUCTION_VERSION||null,iterationId:recordId(latestIteration(project,[10,17,19]),'iterations')||project.job.CURRENT_ITERATION||null,candidateId:recordId(records(project,'candidateFreezes').at(-1),'candidateFreezes')||null,baselineId:recordId(records(project,'baselines').at(-1),'baselines')||project.job.CURRENT_BASELINE_ID||null,productId:recordId(records(project,'products').at(-1),'products')||project.job.CURRENT_PRODUCT_ID||null};}
function scopeMatches(record,scopeRule={}){const rs=record?.scope||{};for(const [key,expected] of Object.entries(scopeRule)){if(expected===undefined)continue;if((rs[key]??null)!==(expected??null))return false;}return true;}
function recordsForCurrentScope(project,collection,scopeRule={}){const active=records(project,collection);const scope={...currentScope(project),...scopeRule};const applicable=Object.fromEntries(Object.entries(scope).filter(([,v])=>v!==undefined&&v!==null));return active.filter(record=>!record.scope||scopeMatches(record,applicable));}
function applicableTests(project,requirement){const req=requirementId(requirement);return recordsForCurrentScope(project,'tests').filter(test=>testRequirementId(test)===req&&!['RETIRED','BLOCKED','NOT READY'].includes(upper(recordValue(test,'STATUS')||'READY')));}
function verificationMatrix(project,iterationId){const requirements=mandatoryRequirements(project);const runs=recordsForCurrentScope(project,'runs',{iterationId}).filter(run=>runIterationId(run)===String(iterationId||''));const verification=recordsForCurrentScope(project,'verification',{iterationId});const expected=[];for(const req of requirements)for(const test of applicableTests(project,req))for(const run of runs)expected.push([requirementId(req),recordId(run,'runs'),recordId(test,'tests')].join('|'));const counts=new Map();for(const record of verification){const key=verificationKey(record);counts.set(key,(counts.get(key)||0)+1);}const missing=expected.filter(key=>!counts.has(key));const duplicates=[...counts].filter(([key,count])=>expected.includes(key)&&count!==1).map(([key,count])=>({key,count}));const invalid=verification.filter(record=>upper(recordValue(record,'INDEPENDENCE_STATUS'))!=='INDEPENDENT'||!String(recordValue(record,'EXACT_EVIDENCE')||'').trim());return {requirements,runs,verification,expected,counts,missing,duplicates,invalid,coverage:expected.length?expected.filter(key=>counts.get(key)===1).length/expected.length:0};}
function currentRegressionExecutions(project,iterationId){return recordsForCurrentScope(project,'regressionExecutions',{iterationId}).filter(record=>!iterationId||String(recordValue(record,'ITERATION_ID')||record.relationships?.ITERATION_ID||record.scope?.iterationId||'')===String(iterationId));}
function evaluateIteration(project,iterationId,mode='INITIAL'){const matrix=verificationMatrix(project,iterationId);const runs=matrix.runs;const contexts=new Set(runs.map(r=>String(recordValue(r,'CONTEXT_ID')||r.relationships?.CONTEXT_ID||r.scope?.contextId||'')));const candidates=new Set(runs.map(r=>String(recordValue(r,'CANDIDATE_ID')||r.relationships?.CANDIDATE_ID||r.scope?.candidateId||'')));const candidateHashes=new Set(runs.map(r=>hash.sha256Value(recordValue(r,'OUTPUT_HASHES')||recordValue(r,'CANDIDATE_HASHES')||r.scope?.candidateId||'')).filter(Boolean));const contaminated=runs.filter(r=>!['NONE','FALSE','CLEAN','NOT CONTAMINATED'].includes(upper(recordValue(r,'CONTAMINATION_CHECK'))));const stage=Number(runs[0]?.stage||0);const rawCount=safe(project.projectData.rawResponses).filter(x=>Number(x.stage)===stage&&!x.invalidatedBy).length;const receiptCount=safe(project.projectData.outputReceipts).filter(x=>Number(x.stage)===stage&&!x.invalidatedBy).length;const comparisons=recordsForCurrentScope(project,'comparisons',{iterationId});const defects=recordsForCurrentScope(project,'defects',{iterationId});const rca=recordsForCurrentScope(project,'rootCauses',{iterationId});const regExec=currentRegressionExecutions(project,iterationId);const unexplained=comparisons.filter(r=>truth(recordValue(r,'CORRECTNESS_AFFECTING_VARIANCE'))&&!truth(recordValue(r,'AUTHORIZED_VARIANCE')));const reasons=[];if(runs.length!==10)reasons.push('Exactly ten current runs are required.');if(contexts.size!==10||contexts.has(''))reasons.push('Ten distinct current fresh contexts are required.');if(candidates.size!==1||candidates.has(''))reasons.push('Exactly one current candidate identity is required.');if(candidateHashes.size>1)reasons.push('Candidate hashes differ across current runs.');if(contaminated.length)reasons.push('A current run is contaminated or contamination is unknown.');if(rawCount<10)reasons.push('Complete raw outputs are not preserved for all ten runs.');if(receiptCount<10)reasons.push('Complete receipts are not preserved for all ten runs.');if(matrix.expected.length===0||matrix.missing.length||matrix.duplicates.length||matrix.invalid.length)reasons.push('The current REQ × RUN × TEST matrix is incomplete or invalid.');if(mode!=='INITIAL'&&!regExec.length&&recordsForCurrentScope(project,'regressions').length)reasons.push('Current regression executions are required.');if(unexplained.length)reasons.push('Unexplained correctness-affecting variance remains.');return {mode,iterationId,runs:runs.map(r=>recordId(r,'runs')),contextCount:contexts.size,candidateIds:[...candidates],matrix,comparisonCount:comparisons.length,defectCount:defects.length,rootCauseCount:rca.length,regressionExecutionCount:regExec.length,unexplainedVarianceCount:unexplained.length,complete:reasons.length===0,reasons};}
function deriveMandatoryTestCoverage(project){const requirements=mandatoryRequirements(project);const covered=requirements.filter(r=>applicableTests(project,r).length).length;return {value:requirements.length?covered/requirements.length:0,inputReferences:requirements.map(requirementId),calculationVersion:'1'};}
function deriveVerificationMatrix(project){const iteration=latestIteration(project,[10,17,19]);const id=recordId(iteration,'iterations');const m=verificationMatrix(project,id);return {value:{expected:m.expected.length,complete:m.expected.length-m.missing.length,missing:m.missing,duplicates:m.duplicates,coverage:m.coverage},inputReferences:[...m.expected],calculationVersion:'1'};}
function deriveConvergence(project){return {value:convergenceMetrics(project),inputReferences:[recordId(latestIteration(project,[17]),'iterations')],calculationVersion:'1'};}
function deriveRelease(project){const value=releaseMetrics(project);return {value,inputReferences:value.inputReferences||[],calculationVersion:'1'};}
function deriveArtifactIdentity(project){const current=records(project,'artifactIdentities');return {value:{authorized:current.length>0&&current.every(r=>upper(recordValue(r,'AUTHORIZATION'))==='AUTHORIZED'),count:current.length},inputReferences:current.map(r=>recordId(r,'artifactIdentities')),calculationVersion:'1'};}
function deriveEvidenceChains(project){const current=records(project,'evidenceChains');return {value:{complete:current.length>0&&current.every(r=>upper(recordValue(r,'STATUS'))==='COMPLETE'),count:current.length},inputReferences:current.map(r=>recordId(r,'evidenceChains')),calculationVersion:'1'};}
const DERIVATIONS=Object.freeze({'stage06.mandatoryTestCoverage':deriveMandatoryTestCoverage,'stage12.verificationMatrix':deriveVerificationMatrix,'stage18.convergence':deriveConvergence,'stage27.release':deriveRelease,'stage28.artifactIdentity':deriveArtifactIdentity,'stage29.evidenceChains':deriveEvidenceChains});
'''
s=s[:anchor]+helpers+'\n'+s[anchor:]

s=replace_func(s,'coverageMetrics',r'''function coverageMetrics(project){const requirements=mandatoryRequirements(project);const tests=recordsForCurrentScope(project,'tests');const covered=new Set(tests.map(testRequirementId).filter(Boolean));const requirementCoverage=requirements.length?requirements.filter(req=>covered.has(requirementId(req))).length/requirements.length:0;const iteration=latestIteration(project,[10,17,19]);const iterationId=recordId(iteration,'iterations')||project.job.CURRENT_ITERATION||'';const matrix=verificationMatrix(project,iterationId);const regressions=recordsForCurrentScope(project,'regressions').filter(r=>upper(recordValue(r,'ACTIVE_RETIRED_STATE')||'ACTIVE')!=='RETIRED');const executions=currentRegressionExecutions(project,iterationId);const successful=new Set(executions.filter(r=>['SATISFIED','SUCCESS','PASSED'].includes(upper(recordValue(r,'RESULT')))).map(r=>String(recordValue(r,'REG_ID')||r.relationships?.REG_ID||'')));return {mandatoryRequirementCount:requirements.length,requirementsWithTests:requirements.filter(req=>covered.has(requirementId(req))).length,requirementCoverage,iterationRunCount:matrix.runs.length,expectedVerificationCount:matrix.expected.length,actualVerificationPairCount:matrix.expected.filter(key=>matrix.counts.get(key)===1).length,actualVerificationTripleCount:matrix.expected.filter(key=>matrix.counts.get(key)===1).length,verificationCoverage:matrix.coverage,missingVerificationTriples:matrix.missing,duplicateVerificationTriples:matrix.duplicates,activeRegressionCount:regressions.length,successfulRegressionCount:regressions.filter(r=>successful.has(recordId(r,'regressions'))).length,regressionSuccess:regressions.length?regressions.filter(r=>successful.has(recordId(r,'regressions'))).length/regressions.length:1};}''')
s=replace_func(s,'convergenceMetrics',r'''function convergenceMetrics(project){const latest=latestIteration(project,[17]);const iterationId=recordId(latest,'iterations');const coverage=coverageMetrics(project);const material=unresolvedMaterialDefects(project).filter(r=>!iterationId||!r.scope?.iterationId||r.scope.iterationId===iterationId);const critical=material.filter(r=>upper(recordValue(r,'SEVERITY'))==='CRITICAL').length;const major=material.filter(r=>upper(recordValue(r,'SEVERITY'))==='MAJOR').length;const verification=recordsForCurrentScope(project,'verification',iterationId?{iterationId}:{});const mandatoryUnknowns=verification.filter(r=>upper(recordValue(r,'DETERMINATION'))==='UNDETERMINED').length+openBlockers(project).length;const comparisons=recordsForCurrentScope(project,'comparisons',iterationId?{iterationId}:{});const contradictions=comparisons.filter(r=>truth(recordValue(r,'ANY_VIOLATION'))&&truth(recordValue(r,'ALL_TEN_SATISFIED'))).length;const ambiguities=comparisons.filter(r=>upper(recordValue(r,'INTERPRETATION_VARIANCE'))&&!falsey(recordValue(r,'INTERPRETATION_VARIANCE'))).length;const unexplainedVariance=comparisons.filter(r=>truth(recordValue(r,'CORRECTNESS_AFFECTING_VARIANCE'))&&!truth(recordValue(r,'AUTHORIZED_VARIANCE'))).length;const result={iterationId,requirementCoverage:coverage.requirementCoverage,verificationCoverage:coverage.verificationCoverage,regressionSuccess:coverage.regressionSuccess,criticalDefects:critical,majorDefects:major,mandatoryUnresolvedUnknowns:mandatoryUnknowns,contradictions,ambiguities,unexplainedVariance};result.converged=Boolean(iterationId)&&result.requirementCoverage===1&&result.verificationCoverage===1&&result.regressionSuccess===1&&critical===0&&major===0&&mandatoryUnknowns===0&&contradictions===0&&ambiguities===0&&unexplainedVariance===0;return result;}''')
s=replace_func(s,'releaseMetrics',r'''function releaseMetrics(project){const requirements=mandatoryRequirements(project);const deterministic=recordsForCurrentScope(project,'deterministicResults');const meaning=recordsForCurrentScope(project,'meaningResults');const adversarial=recordsForCurrentScope(project,'adversarialResults');const inspections=recordsForCurrentScope(project,'representationInspections');const processAudits=recordsForCurrentScope(project,'processAudits');const productAudits=recordsForCurrentScope(project,'productAudits');const regressions=recordsForCurrentScope(project,'regressions').filter(r=>upper(recordValue(r,'ACTIVE_RETIRED_STATE')||'ACTIVE')!=='RETIRED');const regExec=recordsForCurrentScope(project,'regressionExecutions');const baseline=recordsForCurrentScope(project,'baselines').at(-1);const product=recordsForCurrentScope(project,'products').at(-1);const blockers=openBlockers(project);const defects=unresolvedMaterialDefects(project);const failed=[...deterministic,...meaning,...adversarial,...inspections].filter(r=>['VIOLATED','FAILED','REJECTED'].includes(upper(recordValue(r,'DETERMINATION'))));const unknown=[...deterministic,...meaning,...adversarial,...inspections].filter(r=>['UNDETERMINED','UNKNOWN','BLOCKED','NOT RUN'].includes(upper(recordValue(r,'DETERMINATION'))));let satisfied=0,violated=0,undetermined=0;const blockingRequirements=[],violatedRequirements=[];for(const req of requirements){const id=requirementId(req);const results=[...deterministic,...meaning].filter(r=>String(recordValue(r,'REQ_ID')||r.relationships?.REQ_ID||'')===id);if(results.some(r=>upper(recordValue(r,'DETERMINATION'))==='VIOLATED')){violated++;violatedRequirements.push(id);}else if(results.length&&results.every(r=>upper(recordValue(r,'DETERMINATION'))==='SATISFIED'))satisfied++;else{undetermined++;blockingRequirements.push(id);}}const activeRegIds=new Set(regressions.map(r=>recordId(r,'regressions')));const passedReg=new Set(regExec.filter(r=>['SATISFIED','SUCCESS','PASSED'].includes(upper(recordValue(r,'RESULT')))).map(r=>String(recordValue(r,'REG_ID')||r.relationships?.REG_ID||'')));const missingReg=[...activeRegIds].filter(id=>!passedReg.has(id));const auditsOk=processAudits.length>0&&productAudits.length>0&&processAudits.every(r=>upper(recordValue(r,'PROCESS_DETERMINATION'))==='SATISFIED')&&productAudits.every(r=>upper(recordValue(r,'PRODUCT_DETERMINATION'))==='SATISFIED');let determination='ACCEPTED';if(violated||failed.length||defects.some(r=>['CRITICAL','MAJOR'].includes(upper(recordValue(r,'SEVERITY')))))determination='REJECTED';else if(!requirements.length||undetermined||unknown.length||blockers.length||!baseline||!product||!auditsOk||missingReg.length)determination='BLOCKED';const inputReferences=[...requirements.map(requirementId),...deterministic.map(r=>recordId(r,'deterministicResults')),...meaning.map(r=>recordId(r,'meaningResults')),...adversarial.map(r=>recordId(r,'adversarialResults')),...inspections.map(r=>recordId(r,'representationInspections')),...processAudits.map(r=>recordId(r,'processAudits')),...productAudits.map(r=>recordId(r,'productAudits')),...regExec.map(r=>recordId(r,'regressionExecutions')),recordId(baseline,'baselines'),recordId(product,'products')].filter(Boolean);return {determination,mandatoryRequirementCount:requirements.length,satisfied,violated,undetermined,validatorCount:deterministic.length+meaning.length+adversarial.length+inspections.length,failedValidatorIds:failed.map(r=>r.id||r.recordId),unknownValidatorIds:unknown.map(r=>r.id||r.recordId),criticalDefects:defects.filter(r=>upper(recordValue(r,'SEVERITY'))==='CRITICAL').length,majorDefects:defects.filter(r=>upper(recordValue(r,'SEVERITY'))==='MAJOR').length,blockingRequirements,violatedRequirements,blockerIds:blockers.map(r=>recordId(r,'blockers')),missingRegressionIds:missingReg,baselineId:recordId(baseline,'baselines')||null,productId:recordId(product,'products')||null,auditsOk,inputReferences};}''')
s=replace_func(s,'deriveStageData',r'''function deriveStageData(project,stage){ensureShape(project);const derived={};const ids=collection=>recordsForCurrentScope(project,collection).filter(r=>Number(r.stage)===Number(stage)).map(r=>recordId(r,collection));const metrics=coverageMetrics(project);const convergence=convergenceMetrics(project);const release=releaseMetrics(project);switch(stage){case 1:Object.assign(derived,{JOB_ID:project.job.JOB_ID,DATE_OPENED:project.job.DATE_OPENED,INPUT_SET_VERSION:project.job.CURRENT_INPUT_VERSION,INPUT_SET_HASH_OR_MANIFEST:project.job.INPUT_SET_HASH_OR_MANIFEST||'UNKNOWN',JOB_RECORD_STATUS:project.stages[1].status==='COMPLETE'?'READY':'NOT READY'});break;case 2:Object.assign(derived,{SOURCE_SET_VERSION:project.job.CURRENT_SOURCE_SET_VERSION||'NOT APPLICABLE',SOURCE_RECORDS:ids('sources'),SOURCE_CONFLICT_RECORDS:ids('sourceConflicts')});break;case 4:Object.assign(derived,{REQUIREMENTS_VERSION:project.job.CURRENT_REQUIREMENTS_VERSION||'NOT APPLICABLE',TOTAL_REQUIREMENTS:recordsForCurrentScope(project,'requirements').length,MANDATORY_REQUIREMENTS:metrics.mandatoryRequirementCount});break;case 6:Object.assign(derived,{TEST_SUITE_VERSION:project.job.CURRENT_TEST_SUITE_VERSION||'NOT APPLICABLE',TOTAL_ACTIVE_MANDATORY_REQUIREMENTS:metrics.mandatoryRequirementCount,ACTIVE_MANDATORY_REQUIREMENTS_WITH_AT_LEAST_ONE_READY_TEST:metrics.requirementsWithTests,MANDATORY_TEST_COVERAGE:metrics.requirementCoverage});break;case 11:case 17:case 19:{const it=latestIteration(project,[stage]);const ev=evaluateIteration(project,recordId(it,'iterations'),stage===19?'UNCHANGED_CONFIRMATION':stage===17?'CORRECTED':'INITIAL');Object.assign(derived,{ITERATION_ID:ev.iterationId,RUN_COUNT:ev.runs.length,FRESH_CONTEXT_COUNT:ev.contextCount,ITERATION_COMPLETE:ev.complete,ITERATION_REASONS:ev.reasons});break;}case 12:Object.assign(derived,{ACTIVE_MANDATORY_REQUIREMENTS:metrics.mandatoryRequirementCount,RUNS:metrics.iterationRunCount,EXPECTED_MANDATORY_RECORDS:metrics.expectedVerificationCount,ACTUAL_MANDATORY_RECORDS:metrics.actualVerificationTripleCount,MISSING_RECORDS:metrics.missingVerificationTriples.length,VERIFICATION_COVERAGE:metrics.verificationCoverage});break;case 18:Object.assign(derived,{MANDATORY_REQUIREMENT_COVERAGE:convergence.requirementCoverage,MANDATORY_VERIFICATION_COVERAGE:convergence.verificationCoverage,REGRESSION_TEST_SUCCESS:convergence.regressionSuccess,CRITICAL_DEFECTS:convergence.criticalDefects,MAJOR_DEFECTS:convergence.majorDefects,MANDATORY_UNRESOLVED_UNKNOWNS:convergence.mandatoryUnresolvedUnknowns,KNOWN_CORRECTNESS_AFFECTING_CONTRADICTIONS:convergence.contradictions,KNOWN_CORRECTNESS_AFFECTING_AMBIGUITIES:convergence.ambiguities,UNEXPLAINED_CORRECTNESS_AFFECTING_EXECUTION_VARIANCE:convergence.unexplainedVariance,ALL_CONDITIONS_SIMULTANEOUSLY_TRUE:convergence.converged});break;case 27:Object.assign(derived,{TOTAL_MANDATORY_REQUIREMENTS:release.mandatoryRequirementCount,MANDATORY_REQUIREMENTS_WITH_AFFIRMATIVE_SUPPORTING_EVIDENCE:release.satisfied,MANDATORY_REQUIREMENTS_DEMONSTRABLY_VIOLATED:release.violated,MANDATORY_REQUIREMENTS_NOT_ESTABLISHED:release.undetermined,UNRESOLVED_CRITICAL_DEFECTS:release.criticalDefects,UNRESOLVED_MAJOR_DEFECTS:release.majorDefects,SELECTED_RELEASE_STATE:release.determination});break;case 28:Object.assign(derived,DERIVATIONS['stage28.artifactIdentity'](project).value);break;case 29:Object.assign(derived,DERIVATIONS['stage29.evidenceChains'](project).value);break;}derived.STAGE_DECISION=project.stages[stage].status==='COMPLETE'?'READY TO PROCEED':project.stages[stage].status==='BLOCKED'?'BLOCKED':'NOT READY - CORRECTION REQUIRED';derived.DECISION_EVIDENCE=project.stages[stage].gate?.reasons?.length?project.stages[stage].gate.reasons.join('; '):'Canonical current-scope records and deterministic calculations satisfy the stage gate.';return derived;}''')
s=s.replace('    state.acceptedData=deriveStageData(project,stage);','    state.derivedData=deriveStageData(project,stage);')
s=replace_func(s,'invalidateDownstream',r'''function invalidateDownstream(project,stage,changeId,reason='Material upstream change'){ensureShape(project);const invalidatedStages=[];for(let number=Number(stage)+1;number<=30;number++){const state=project.stages[number];if(state.status!=='NOT STARTED'||state.acceptedDataChangeIds.length||state.acceptedControlEventIds.length)invalidatedStages.push(number);state.status='NOT STARTED';state.invalidatedBy=changeId;state.gate={complete:false,blocked:false,reasons:['Invalidated by '+changeId+': '+reason+'.']};for(const collection of Object.keys(schema.RECORD_SCHEMAS)){for(const record of records(project,collection,{stage:number,active:false}))if(!record.invalidatedBy){record.invalidatedBy=changeId;record.active=false;record.validity='INVALIDATED';}}for(const change of safe(project.projectData.acceptedChanges).filter(x=>Number(x.stage)===number&&!x.invalidatedBy))change.invalidatedBy=changeId;for(const prompt of safe(project.projectData.generatedPrompts).filter(x=>Number(x.stage)===number&&!x.invalidatedBy))prompt.invalidatedBy=changeId;for(const proposal of safe(project.projectData.responseProposals).filter(x=>Number(x.stage)===number&&!x.invalidatedBy&&x.status==='PENDING_OPERATOR_REVIEW')){proposal.invalidatedBy=changeId;proposal.status='STALE';}for(const confirmation of safe(project.projectData.stageConfirmations).filter(x=>Number(x.stage)===number&&!x.invalidatedBy))confirmation.invalidatedBy=changeId;}for(const collection of ['releaseRecords','artifactIdentities','evidenceChains','convergenceRecords'])for(const record of records(project,collection,{active:false}))if(!record.invalidatedBy){record.invalidatedBy=changeId;record.active=false;record.validity='INVALIDATED';}project.release.gateState='';project.release.authorization='NOT AUTHORIZED';project.release.authorizedArtifactIds=[];addHistory(project,'DOWNSTREAM_INVALIDATED',{stage,changeId,reason,invalidatedStages});recalculate(project);return invalidatedStages;}''')
s=replace_func(s,'recordReleaseDetermination',r'''function recordReleaseDetermination(project){ensureShape(project);const metrics=releaseMetrics(project);const releaseEvidenceSha256=hash.sha256Value({metrics,inputReferences:metrics.inputReferences});const existing=records(project,'releaseRecords').find(r=>r.releaseEvidenceSha256===releaseEvidenceSha256);if(existing)return existing;for(const prior of records(project,'releaseRecords',{active:false}))if(!prior.invalidatedBy){prior.active=false;prior.validity='SUPERSEDED';prior.invalidatedBy='RELEASE-EVIDENCE-CHANGED';}project.release.authorization='NOT AUTHORIZED';project.release.authorizedArtifactIds=[];const id=allocateId(project,'releaseRecords');const fields={RELEASE_ID:id,PRODUCT_ID:metrics.productId||'UNKNOWN',BASELINE_ID:metrics.baselineId||'UNKNOWN',DETERMINATION:metrics.determination,MANDATORY_REQUIREMENT_COUNTS:metrics.mandatoryRequirementCount,AFFIRMATIVE_EVIDENCE_COUNTS:metrics.satisfied,VIOLATED_COUNTS:metrics.violated,UNDETERMINED_COUNTS:metrics.undetermined,VALIDATOR_COUNTS:metrics.validatorCount,FAILED_VALIDATORS:metrics.failedValidatorIds,UNKNOWN_VALIDATORS:metrics.unknownValidatorIds,CRITICAL_DEFECTS:metrics.criticalDefects,MAJOR_DEFECTS:metrics.majorDefects,BLOCKING_REQUIREMENTS:metrics.blockingRequirements,VIOLATIONS:metrics.violatedRequirements,BLOCKERS:metrics.blockerIds,CONTROLLING_EVIDENCE:releaseEvidenceSha256};const record={id,stage:27,createdAt:now(),active:true,fields,...fields,releaseEvidenceSha256,scope:currentScope(project),sha256:hash.sha256Value(fields),source:'APPLICATION_DERIVATION',derivationKey:'stage27.release'};project.projectData.releaseRecords.push(record);project.release.gateState=metrics.determination;addHistory(project,'RELEASE_DETERMINATION_CALCULATED',{recordId:id,determination:metrics.determination,releaseEvidenceSha256});recalculate(project);return record;}''')
s=replace_func(s,'verifyArtifactIdentity',r'''function verifyArtifactIdentity(project,audited,delivery){ensureShape(project);if(upper(recordValue(records(project,'releaseRecords').at(-1),'DETERMINATION'))!=='ACCEPTED')throw new Error('Artifact identity verification is prohibited until Stage 27 is ACCEPTED.');const a=safe(audited),d=safe(delivery);const duplicate=(list,key)=>{const seen=new Set();for(const x of list){const v=String(x[key]??'');if(!v||seen.has(v))return true;seen.add(v);}return false;};if(duplicate(a,'artifactId')||duplicate(d,'artifactId')||duplicate(a,'name')||duplicate(d,'name'))throw new Error('Duplicate artifact identity or filename is prohibited.');const byId=new Map(d.map(x=>[String(x.artifactId),x]));if(a.length!==d.length)throw new Error('Audited and delivery artifact counts differ.');const created=[];for(const left of a){const right=byId.get(String(left.artifactId));if(!right)throw new Error('Missing delivery artifact '+left.artifactId+'.');const id=allocateId(project,'artifactIdentities');const fields={IDENTITY_ID:id,ARTIFACT_ID:left.artifactId,AUDITED_FILENAME:left.name,AUDITED_VERSION:left.version||'UNKNOWN',AUDITED_STORAGE_REFERENCE:left.storageReference||'INDEXEDDB',AUDITED_BYTE_SIZE:left.size,AUDITED_SHA256:left.sha256,RELEASE_FILENAME:right.name,RELEASE_VERSION:right.version||'UNKNOWN',RELEASE_STORAGE_REFERENCE:right.storageReference||'INDEXEDDB',RELEASE_BYTE_SIZE:right.size,PRE_DELIVERY_SHA256:right.sha256,EXACT_HASH_MATCH:Boolean(left.sha256&&right.sha256&&left.sha256===right.sha256),EXACT_SIZE_MATCH:Number(left.size)===Number(right.size),POST_AUDIT_MODIFICATION_EVIDENCE:left.sha256===right.sha256?'NONE':'MISMATCH',AUTHORIZATION:'NOT AUTHORIZED'};fields.AUTHORIZATION=fields.EXACT_HASH_MATCH&&fields.EXACT_SIZE_MATCH&&fields.AUDITED_FILENAME===fields.RELEASE_FILENAME?'AUTHORIZED':'NOT AUTHORIZED';if(fields.AUTHORIZATION!=='AUTHORIZED')throw new Error('Artifact '+left.artifactId+' does not exactly match audited identity.');const record={id,stage:28,createdAt:now(),active:true,fields,...fields,scope:currentScope(project),sha256:hash.sha256Value(fields),source:'APPLICATION_DERIVATION',derivationKey:'stage28.artifactIdentity'};project.projectData.artifactIdentities.push(record);created.push(record);}project.release.authorization=created.length&&created.every(r=>r.AUTHORIZATION==='AUTHORIZED')?'AUTHORIZED':'NOT AUTHORIZED';project.release.authorizedArtifactIds=created.map(r=>r.ARTIFACT_ID);addHistory(project,'ARTIFACT_IDENTITY_VERIFIED',{count:created.length,authorization:project.release.authorization});recalculate(project);return created;}''')
